const { chromium } = require('playwright');
const fs = require('fs');
const os = require('os');
const path = require('path');

const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36';
const MAIN = 'https://onlinelibrary.wiley.com/doi/10.1002/anie.201914416';
const SI = 'https://pericles.pericles-prod.literatumonline.com/action/downloadSupplement?doi=10.1002%2Fanie.201914416&file=anie201914416-sup-0001-misc_information.pdf';

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--disable-blink-features=AutomationControlled'] });
  const context = await browser.newContext({ userAgent: UA, viewport: { width: 1400, height: 900 }, locale: 'en-US' });
  const page = await context.newPage();
  await page.addInitScript(() => { Object.defineProperty(navigator, 'webdriver', { get: () => undefined }); });

  // Step 1: main article page
  let html = '';
  for (let i = 0; i < 5; i++) {
    try {
      await page.goto(MAIN, { waitUntil: 'domcontentloaded', timeout: 60000 });
      await sleep(9000);
      html = await page.content();
      console.log('MAIN try', i, 'title=', (await page.title()).slice(0, 80), 'len=', html.length);
      if (!/Just a moment|请稍候/.test(html)) break;
    } catch (e) { console.log('MAIN err', e.message); }
  }
  fs.writeFileSync(path.join(os.tmpdir(), 'wiley_pw_main.html'), html);

  // Step 2: SI on pericles domain (get CF cookies)
  for (let i = 0; i < 5; i++) {
    try {
      await page.goto(SI, { waitUntil: 'domcontentloaded', timeout: 60000 });
      await sleep(9000);
      const t = await page.title();
      console.log('SI try', i, 'title=', t.slice(0, 80));
      if (!/Just a moment|请稍候/.test(t)) break;
    } catch (e) { console.log('SI err', e.message); }
  }

  // Step 3: download SI with cookies via node fetch
  const cookies = await context.cookies('https://pericles.pericles-prod.literatumonline.com');
  const cookieStr = cookies.map(c => c.name + '=' + c.value).join('; ');
  console.log('cookies:', cookies.map(c => c.name).join(','));
  try {
    const r = await fetch(SI, { headers: { 'User-Agent': UA, 'Cookie': cookieStr, 'Accept': 'application/pdf,*/*' }, redirect: 'follow' });
    const buf = Buffer.from(await r.arrayBuffer());
    console.log('SI fetch status:', r.status, 'bytes:', buf.length, 'head:', buf.slice(0, 8).toString());
    fs.writeFileSync(path.join(os.tmpdir(), 'si_pw.pdf'), buf);
  } catch (e) { console.log('SI fetch err', e.message); }

  await browser.close();
  console.log('DONE');
})().catch(e => { console.error('FATAL', e.message); process.exit(1); });

import os, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8', errors='replace')
from playwright.sync_api import sync_playwright

UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Safari/537.36'
MAIN = 'https://onlinelibrary.wiley.com/doi/10.1002/anie.201914416'
SI = 'https://onlinelibrary.wiley.com/action/downloadSupplement?doi=10.1002%2Fanie.201914416&file=anie201914416-sup-0001-misc_information.pdf'
TMP = os.environ.get('TEMP', '.')

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True, args=['--disable-blink-features=AutomationControlled'])
    ctx = browser.new_context(user_agent=UA, viewport={'width': 1400, 'height': 900}, locale='en-US', accept_downloads=True)
    page = ctx.new_page()
    page.add_init_script("Object.defineProperty(navigator, 'webdriver', {get: () => undefined});")

    for i in range(6):
        try:
            page.goto(MAIN, wait_until='domcontentloaded', timeout=60000)
            page.wait_for_timeout(9000)
            title = page.title()
            print(f'MAIN try {i}: {title[:60]!r}')
            if 'Just a moment' not in title and '请稍候' not in title:
                break
        except Exception as e:
            print('MAIN err', str(e)[:100])

    # Navigate to SI inside the real page; after CF challenge passes, PDF download fires
    try:
        with page.expect_download(timeout=150000) as dl_info:
            try:
                page.goto(SI, wait_until='commit', timeout=60000)
            except Exception as e:
                print('goto SI note:', str(e)[:80])
            # wait for challenge to pass and download to trigger
            dl = dl_info.value
            dl.save_as(os.path.join(TMP, 'si_anie201914416.pdf'))
            print('SI DOWNLOAD SAVED, suggested filename:', dl.suggested_filename)
    except Exception as e:
        print('SI download err:', str(e)[:200])
        # fallback: in-page fetch after challenge
        try:
            for _ in range(15):
                t = page.title()
                if 'Just a moment' not in t and '请稍候' not in t:
                    break
                page.wait_for_timeout(5000)
            print('page title after wait:', page.title()[:60])
            b64 = page.evaluate('''async () => {
              const r = await fetch(location.href, {credentials: 'include'});
              const b = await r.arrayBuffer();
              let bin = '';
              const u = new Uint8Array(b);
              const CH = 0x8000;
              for (let i = 0; i < u.length; i += CH) bin += String.fromCharCode.apply(null, u.subarray(i, i + CH));
              return btoa(bin);
            }''')
            import base64
            data = base64.b64decode(b64)
            print('in-page fetch bytes:', len(data), 'head:', data[:8])
            if data[:4] == b'%PDF':
                open(os.path.join(TMP, 'si_anie201914416.pdf'), 'wb').write(data)
                print('SI SAVED VIA FETCH')
        except Exception as e2:
            print('fallback err:', str(e2)[:200])

    browser.close()
    print('DONE')
